from review import card,save,DATE

i='TCS-3146';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 1.1, p. 2 (the missing n²/k⁴ versus n²/k² gap); Section 2.1 (polynomially bounded integer query coefficients), Section 2.2 (edge-probe upper bound), Corollary 12 and Section 6, p. 14. Corollary 12 explicitly uses k=n^γ for fixed 0<γ<1/2.'
refs.append(dict(id='version',title='Average-Case Communication Complexity of Statistical Problems — author version record',authors='Cyrus Rashtchian; David P. Woodruff; Peng Ye; Hanlin Zhu',year=2021,url='https://arxiv.org/abs/2107.01335',locator='Version 1, 3 July 2021, COLT 2021 paper; no later arXiv revision listed when checked 12 September 2026.'))
save(i,dict(title='Adaptive linear-sketch query complexity of planted-clique detection',formal='For every fixed 0<γ<1/2 and every fixed integer B≥1, determine, up to factors polynomial in log n, the minimum number Q_B(n,k) of adaptive integer linear queries needed to distinguish G(n,1/2) from G(n,1/2,k), with error at most 1/10 under each hypothesis, where k=⌈n^γ⌉. A query has integer coefficients of absolute value at most n^B and returns one exact scalar linear combination of the adjacency entries. The source’s quantitative gap, in the polynomial-clique-size regime of Corollary 12, is between Õ(n²/k⁴) lower bounds and Õ(n²/k²) upper bounds. Determine where the actual complexity lies in this gap; do not assume either endpoint is the answer.',definitions='Under the null hypothesis, G is a simple undirected graph on [n] in which every unordered pair is independently an edge with probability 1/2. Under the planted hypothesis, choose a k-element set K⊆[n] uniformly at random, set every edge inside K to present, and independently include every other pair with probability 1/2. Let A∈{0,1}^{n×n} be the symmetric adjacency matrix with zero diagonal. A query supplies integers u_{ij} with |u_{ij}|≤n^B and receives Σᵢ₌₁ⁿΣⱼ₌₁ⁿu_{ij}A_{ij}, computed over the integers, not modulo two. The answer has O((B+2)log n) bits. The next query may depend on previous answers and fresh independent random bits; the algorithm has no access to A except through these queries. It outputs one bit identifying the hypothesis, with failure probability at most 1/10 separately for a null graph and a planted graph. Probability includes the graph, the planted set and algorithmic randomness. No polynomial-time, storage or query-construction-time bound is imposed; cost counts the maximum number of scalar oracle queries over all answer and coin sequences. Q_B is the minimum such maximum over algorithms for n,k with the stated coefficient bound. The bound B is fixed before letting n grow: allowing an arbitrarily large coefficient exponent separately at each input size is not the model. Likewise γ is fixed as n→∞; constants in the asymptotic bounds may depend on B and γ. Matching up to polylogarithmic factors means a proved upper/lower ratio at most (log(n+1))^a times a constant, with a fixed independently of n. An edge probe is a permitted query with one coefficient equal to one and the rest zero. General real coefficients of unlimited precision, an entire vector response, recovery of K, and a worst-case arbitrary input graph are different problems.',question_type='asymptotic_complexity',answer_criterion='Give matching upper and lower bounds for Q_B(n,⌈n^γ⌉), up to polylogarithmic factors, for each fixed B≥1 and 0<γ<1/2. Lower bounds must allow adaptive queries and unrestricted computation, and upper bounds must obey the polynomial integer-coefficient restriction. Bounds for the edge-probe, parity-sketch, semirandom or promised-location variant alone do not settle this target.',context_blocks=[dict(title='A planted signal observed through aggregate measurements',text='The graph is otherwise random, but the planted hypothesis contains a uniformly positioned complete subgraph. A linear query can combine many edge indicators into one answer, potentially exposing information that would take many individual edge probes to obtain.',citation='primary'),dict(title='The unresolved gap is a power of the planted size',text='The paper gives a general linear-query lower bound of order n²/k⁴ up to logarithmic losses and an edge-probe upper bound of order n²/k² up to such factors. Its conclusion asks for the correct complexity between these bounds. The card uses the polynomial k regime stated in the lower-bound theorem, without extending that theorem to threshold-size cliques.',citation='primary'),dict(title='Coefficient precision is part of the question',text='Section 2.1 requires polynomially bounded integer coefficients even though the algebraic expressions are written over the reals. An arbitrary-precision real measurement could encode much more information in one answer. Keeping the integer and magnitude requirements prevents a different oracle from replacing the one actually studied.',citation='primary'),dict(title='Related variants have different answers',text='The paper obtains tighter results for parity sketches, a semirandom planting model and a promise on possible planted locations. Those results are separately stated and do not close the ordinary randomly located planted-clique gap in the general linear model.',citation='primary')],why='Would determine how much aggregate linear measurements can improve on individual edge queries for a central average-case detection problem, separating information access from computation-time hardness.',references=refs,progress=[dict(date='2021',text='Corollary 12 proves the Õ(n²/k⁴) lower bound for k=n^γ, 0<γ<1/2; existing edge-probe algorithms supply the Õ(n²/k²) upper bound. The conclusion leaves the gap open.',citation='primary')],status='source_open',status_note='Read the complete COLT 2021 paper, including integer precision, adaptive-query scope, the explicit Corollary 12 parameter regime and the distinct model variants. Checked the arXiv version record and searched later work through 12 September 2026; no result closing this ordinary linear-query gap was found. Searches are not exhaustive.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A concrete test of the information gained from aggregate measurements in average-case graph detection, with implications for sketching and query lower bounds. Existing score retained.',assessed_on=DATE),review_note='Restored the planted-clique detection task and both missing powers of k. Used the polynomial clique-size regime expressly stated in Corollary 12, defined fixed polynomial coefficient precision, adaptivity, scalar output and error, and kept alternative planting/sketch models separate.',working_summary=dict(sentences=['The algorithm distinguishes a random graph from one with a uniformly planted clique.','It can adaptively query integer linear combinations of adjacency entries with polynomially bounded coefficients.','The cost is the number of scalar queries, with no computation-time restriction.','For polynomial clique sizes below √n, the source leaves a gap between n²/k⁴ and n²/k² up to logarithmic factors.','The target is matching bounds in this exact oracle and planting model, rather than recovering the clique or solving a promise variant.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','version'])),notes=['Recovered planted-clique detection and the n²/k⁴ versus n²/k² query gap.','Specified the Corollary 12 polynomial-size regime and fixed coefficient-exponent quantifiers.','Defined the graph distributions, adaptive integer linear queries, exact scalar answers and constant error.','Separated parity, edge-probe, promise-location and semirandom variants.'],checked_sources=[r['url'] for r in refs])
